// Generated by sel-pull (Shared Element Library): do not edit, it is replaced by the next "sel-pull firebase".
//
// npm run dev: the whole app on this machine, as it runs in production but against local data. Starts the Firebase emulators configured
// in firebase.json (Hosting with its headers, Firestore with the real rules, Auth with a fake sign-in). The local database is kept between
// runs (saved to .emulator/data when you stop with Ctrl+C); a run that starts with an empty database fills it with the demo data from
// scripts/dev-seed.mjs. Reset it with npm run dev:seed, or copy the live data in with npm run dev:pull.
import fs from "node:fs";
import path from "node:path";
import { spawn } from "node:child_process";
import { ROOT, DATA_DIR, SEED_FILE, PENDING_COPY, HOSTING_URL, UI_URL, emulatorsRunning, isEmpty } from "./emulator.mjs";
import { DEV_CONFIG_FILE, devRuntime } from "./dev-config.mjs";
import { startDevProxy } from "./dev-proxy.mjs";

/**
 * Runs one of the dev scripts to the end and says how it went ({ status, error }). Not spawnSync: that blocks this whole process, and the dev proxy (dev-proxy.mjs)
 * lives in it, so the app would not answer at all while a live copy of the data loads (which takes a while).
 */
const run = (args) =>
  new Promise((resolve) => {
    const child = spawn(process.execPath, args, { stdio: "inherit" });
    child.on("error", (error) => resolve({ status: 1, error }));
    child.on("exit", (status) => resolve({ status: status ?? 1 }));
  });

if (await emulatorsRunning()) console.log(`The emulators are already running${HOSTING_URL ? `: ${HOSTING_URL}` : "."}`);
else await start();

async function start() {
  const saved = path.join(DATA_DIR, "data");
  // The emulators run with a copy of firebase.json (see dev-config.mjs): an enforced Content-Security-Policy would block the page's own connections to the
  // emulators, and the Hosting emulator sits behind a proxy that stops browsers from caching what it serves.
  const runtime = devRuntime(JSON.parse(fs.readFileSync(path.join(ROOT, "firebase.json"), "utf8")));
  fs.writeFileSync(path.join(ROOT, DEV_CONFIG_FILE), JSON.stringify(runtime.config, null, 2) + String.fromCharCode(10));
  let command = `firebase emulators:start --config ${DEV_CONFIG_FILE} --export-on-exit "${saved}"`;
  if (fs.existsSync(path.join(saved, "firebase-export-metadata.json"))) command += ` --import "${saved}"`;

  // The emulator variables this process set for itself must not reach the CLI.
  const env = { ...process.env };
  for (const name of ["FIRESTORE_EMULATOR_HOST", "FIREBASE_AUTH_EMULATOR_HOST", "METADATA_SERVER_DETECTION"]) delete env[name];
  const firebase = spawn(command, { cwd: ROOT, env, stdio: "inherit", shell: true });
  firebase.on("error", () => console.error("Could not run the Firebase CLI. Install it with: npm install -g firebase-tools (the emulators also need Java)"));
  firebase.on("exit", (code) => process.exit(code ?? 0));
  process.on("SIGINT", () => {}); // Ctrl+C reaches the CLI too; it saves the data and exits, and then so does this

  const proxy = runtime.proxy ? startDevProxy(runtime.proxy) : null;
  proxy?.on("error", (err) => {
    console.error(`\nThe app's address ${HOSTING_URL} could not be opened (${err.code || err.message}): another program is probably using that port. Stop it (another project's emulators?), or change emulators.hosting.port in firebase.json.`);
    firebase.kill();
    process.exit(1);
  });
  firebase.on("exit", () => proxy?.close());

  for (let i = 0; i < 120 && !(await emulatorsRunning()); i++) await new Promise((r) => setTimeout(r, 500));
  if (!(await emulatorsRunning())) {
    console.error("The emulators didn't start within a minute; see the output above.");
    firebase.kill();
    process.exit(1);
  }

  // A failed load or seed leaves the emulators running (and the exit code of this script alone), but the banner must not say "ready".
  let problem = null;
  if (fs.existsSync(PENDING_COPY)) {
    console.log("\nLoading the live copy made while the emulators were stopped (npm run dev:load).");
    const loaded = await run([path.join(ROOT, "scripts/sel-dev/load.mjs"), fs.readFileSync(PENDING_COPY, "utf8").trim() || path.join(DATA_DIR, "live-copy.json")]);
    if (loaded.error || loaded.status !== 0) {
      problem = "The live copy was NOT loaded (see above); the emulators keep what they had (or, if the error says the data was cleared, hold incomplete data). It stays queued: fix it, then run npm run dev:load.";
      console.error(`\n${problem}`);
    }
  } else if (fs.existsSync(SEED_FILE)) {
    let empty = false;
    try {
      empty = await isEmpty();
    } catch (err) {
      problem = `The local database could not be checked (${err.message}), so it was NOT filled with the demo data. When you are sure it is empty, run: npm run dev:seed`;
      console.error(`\n${problem}`);
    }
    if (empty) {
      console.log("\nEmpty local database: filling it with the demo data (npm run dev:seed).");
      const seeded = await run([path.join(ROOT, "scripts/sel-dev/seed.mjs")]);
      if (seeded.error || seeded.status !== 0) {
        problem = "The demo data was NOT loaded (see above); the local database is empty or incomplete. Fix scripts/dev-seed.mjs, then run npm run dev:seed.";
        console.error(`\n${problem}`);
      }
    }
  }

  console.log([
    "",
    problem && "  NOT READY     The local data is not set up (see the message above). The emulators are running; the app is at the address below.",
    HOSTING_URL && `  App           ${HOSTING_URL}   (sign in with the emulator's account picker)`,
    UI_URL && `  Emulator UI   ${UI_URL}   (browse and edit the local data and accounts, see which rule allowed a request)`,
    "  Reset data    npm run dev:seed      Live copy   npm run dev:pull      Stop   Ctrl+C (keeps the local data)",
    "",
  ].filter((l) => typeof l === "string").join("\n"));
}
